import { useEffect, useState, useRef } from "react";

// ── Silent visual metronome ────────────────────────────────────────────────
// A beat-synced pulse around the outer edge of the page-viewing area — no
// sound, doesn't block the score. Sits as a sibling of the canvas container
// (not per-pane), so it overlays single/spread/half layouts identically.
// Pulses by toggling box-shadow/opacity for ~90ms on every beat change
// (not a free-running CSS animation) so it never drifts if tempo changes.
export default function VisualMetronomeBorder({ beat, accentColor = "#e07b39", color = "#4a7c59" }) {
  const [flash, setFlash] = useState(false);
  const lastBeatRef = useRef(beat);

  useEffect(() => {
    if (beat === lastBeatRef.current) return;
    lastBeatRef.current = beat;
    if (beat === 0) return; // metronome stopped
    setFlash(true);
    const t = setTimeout(() => setFlash(false), 90);
    return () => clearTimeout(t);
  }, [beat]);

  const glow = beat === 1 ? accentColor : color;

  return (
    <div
      style={{
        position: "absolute", inset: 0, zIndex: 8, pointerEvents: "none",
        boxShadow: flash ? `inset 0 0 0 6px ${glow}, inset 0 0 28px 4px ${glow}99` : "inset 0 0 0 0 transparent",
        transition: "box-shadow 0.07s ease-out",
      }}
    />
  );
}
