// ── Musical stamps: hairpins (crescendo/diminuendo), dynamics, fingering ──
// Drawn procedurally on canvas — no image assets needed. Each stamp item:
//   { type: "stamp", kind, x, y, w, h, rotation: 0, text? }
// (x,y,w,h) is the stamp's bounding box in full-page canvas coordinates —
// same space freehand strokes already use, so stamps live in the SAME
// per-page `strokes[key]` array and are fully transparent to undo/redo.

export const STAMP_KINDS = [
  { id: "hairpin-cresc", label: "Crescendo" },
  { id: "hairpin-dim",   label: "Diminuendo" },
  { id: "dynamic",       label: "Dinámica" },
  { id: "fingering",     label: "Dedo" },
];

export const DYNAMIC_TEXTS   = ["pp", "p", "mp", "mf", "f", "ff", "sfz"];
export const FINGERING_TEXTS = ["1", "2", "3", "4", "5"];

function drawHairpin(ctx, item, opening) {
  const { x, y, w, h, color = "#1a1a1a" } = item;
  const midY = y + h / 2;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth   = Math.max(1.5, h * 0.08);
  ctx.lineCap     = "round";
  ctx.beginPath();
  if (opening) {
    // crescendo: narrow on the left, wide on the right  <
    ctx.moveTo(x, midY);
    ctx.lineTo(x + w, y);
    ctx.moveTo(x, midY);
    ctx.lineTo(x + w, y + h);
  } else {
    // diminuendo: wide on the left, narrow on the right  >
    ctx.moveTo(x, y);
    ctx.lineTo(x + w, midY);
    ctx.moveTo(x, y + h);
    ctx.lineTo(x + w, midY);
  }
  ctx.stroke();
  ctx.restore();
}

function drawText(ctx, item) {
  const { x, y, w, h, text = "", color = "#1a1a1a" } = item;
  ctx.save();
  ctx.fillStyle = color;
  ctx.font = `italic 700 ${Math.max(12, h * 0.8)}px 'Playfair Display', Georgia, serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.fillText(text, x + w / 2, y + h / 2);
  ctx.restore();
}

export function drawStamp(ctx, item, selected) {
  switch (item.kind) {
    case "hairpin-cresc": drawHairpin(ctx, item, true); break;
    case "hairpin-dim":   drawHairpin(ctx, item, false); break;
    case "dynamic":
    case "fingering":     drawText(ctx, item); break;
    default: break;
  }
  if (selected) {
    ctx.save();
    ctx.strokeStyle = "#2e74b5";
    ctx.lineWidth = 1.5;
    ctx.setLineDash([4, 3]);
    ctx.strokeRect(item.x - 3, item.y - 3, item.w + 6, item.h + 6);
    ctx.restore();
  }
}

// Default size/text for a newly placed stamp of a given kind, centered on (x, y).
export function makeStamp(kind, x, y, extra = {}) {
  const base = { id: `stamp-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, type: "stamp", kind, color: "#1a1a1a" };
  if (kind === "hairpin-cresc" || kind === "hairpin-dim") {
    return { ...base, x: x - 40, y: y - 10, w: 80, h: 20, ...extra };
  }
  // dynamic / fingering
  return { ...base, x: x - 16, y: y - 14, w: 32, h: 28, text: extra.text || (kind === "dynamic" ? "mf" : "1"), ...extra };
}

// Hit test — is (px, py) inside this stamp's bounding box?
export function hitTestStamp(item, px, py) {
  return px >= item.x && px <= item.x + item.w && py >= item.y && py <= item.y + item.h;
}

// Corner resize-handle hit test (bottom-right handle, ~14px square)
export function hitTestResizeHandle(item, px, py) {
  const hx = item.x + item.w, hy = item.y + item.h;
  return Math.abs(px - hx) <= 10 && Math.abs(py - hy) <= 10;
}
