import { useRef, useState, useLayoutEffect, useCallback } from "react";

// ── Half-page (top/bottom) split layout ───────────────────────────────────
// Shows the BOTTOM portion of the current page and the TOP portion of the
// next page, stacked vertically, with a draggable divider between them.
//
// Both pages are rendered at full height exactly like in single-page mode —
// this component only controls CLIPPING via two fixed-height `overflow:
// hidden` wrappers. The top pane's inner content is anchored to its own
// bottom edge (`bottom:0`) so the page's top portion is clipped away,
// leaving its bottom slice visible; the bottom pane's content is anchored
// to its own top edge (`top:0`) so the next page's bottom is clipped away.
// No coordinate translation is needed for drawing/pointer handling because
// the canvases themselves are never resized or redrawn — only an ancestor's
// clip box changes, and browsers don't dispatch pointer events into a
// clipped-away area, so touches naturally land on the right page already.
//
// Pane sizes are explicit PIXEL heights (measured via ResizeObserver), not
// CSS percentages — percentage heights nested inside a flex item have a
// long history of inconsistent resolution on WebKit/Safari, and this view
// is exactly that shape (flex item → 100% height → percentage-height
// children), so pixels sidestep the ambiguity entirely.
export default function HalfPageView({ frac, onFracChange, topPane, bottomPane }) {
  const containerRef = useRef(null);
  const dragRef       = useRef(false);
  const [containerH, setContainerH] = useState(0);

  useLayoutEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const measure = () => setContainerH(el.clientHeight);
    measure();
    if (typeof ResizeObserver !== "undefined") {
      const ro = new ResizeObserver(measure);
      ro.observe(el);
      return () => ro.disconnect();
    }
    // No ResizeObserver (very old WebKit) — fall back to a window resize
    // listener plus one retry shortly after mount, in case layout wasn't
    // fully settled on the very first synchronous measurement.
    window.addEventListener("resize", measure);
    const t = setTimeout(measure, 200);
    return () => { window.removeEventListener("resize", measure); clearTimeout(t); };
  }, []);

  const clampFrac = (f) => Math.min(0.85, Math.max(0.15, f));

  const updateFromClientY = useCallback((clientY) => {
    const el = containerRef.current;
    if (!el) return;
    const rect = el.getBoundingClientRect();
    const f = (clientY - rect.top) / rect.height;
    onFracChange(clampFrac(f));
  }, [onFracChange]);

  // stopPropagation on every divider event — the ancestor canvas container
  // has its own tap-to-reveal/hide gesture on plain pointerdown/up; without
  // this, a small divider nudge also bubbles up and gets misread as a tap,
  // toggling all the floating controls off right as the user adjusts it.
  const onDividerDown = (e) => {
    e.preventDefault();
    e.stopPropagation();
    e.currentTarget.setPointerCapture?.(e.pointerId);
    dragRef.current = true;
  };
  const onDividerMove = (e) => {
    if (!dragRef.current) return;
    e.preventDefault();
    e.stopPropagation();
    updateFromClientY(e.clientY);
  };
  const onDividerUp = (e) => { e.stopPropagation(); dragRef.current = false; };

  const DIVIDER_H = 14;
  const usableH   = Math.max(0, containerH - DIVIDER_H);
  const topH      = Math.round(usableH * frac);
  const bottomH   = usableH - topH;

  return (
    <div ref={containerRef} style={{ position: "relative", width: "100%", height: "100%" }}>
      <div style={{ position: "absolute", top: 0, left: 0, right: 0, height: topH, overflow: "hidden" }}>
        <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, display: "flex", justifyContent: "center" }}>
          {topPane}
        </div>
      </div>

      {/* ── Draggable divider ── */}
      <div
        onPointerDown={onDividerDown}
        onPointerMove={onDividerMove}
        onPointerUp={onDividerUp}
        onPointerCancel={onDividerUp}
        style={{
          position: "absolute", top: topH, left: 0, right: 0, height: DIVIDER_H,
          cursor: "row-resize", touchAction: "none",
          display: "flex", alignItems: "center", justifyContent: "center",
          background: "rgba(74,124,89,0.25)", zIndex: 5,
        }}
      >
        <div style={{ width: 44, height: 4, borderRadius: 2, background: "#4a7c59" }} />
      </div>

      <div style={{ position: "absolute", top: topH + DIVIDER_H, left: 0, right: 0, height: bottomH, overflow: "hidden" }}>
        <div style={{ position: "absolute", left: 0, right: 0, top: 0, display: "flex", justifyContent: "center" }}>
          {bottomPane}
        </div>
      </div>
    </div>
  );
}
