import { PDFDocument } from "pdf-lib";

// ── Page-level PDF editing (reorder / delete / split / extract) ──────────
// All functions take and return raw PDF bytes (ArrayBuffer/Uint8Array) —
// they never touch pdf.js or the live viewer; ScoreViewer wires the result
// back into the library once the user confirms the edit.

// Rebuilds the document with pages in `order` (0-based indices into the
// original document) — used for both reordering and deleting (omit an
// index to delete that page).
export async function rebuildWithOrder(bytes, order) {
  const src = await PDFDocument.load(bytes);
  const out = await PDFDocument.create();
  const copied = await out.copyPages(src, order);
  copied.forEach(p => out.addPage(p));
  return out.save();
}

export function reorderPages(bytes, newOrder) {
  return rebuildWithOrder(bytes, newOrder);
}

export function deletePages(bytes, indicesToDelete, totalPages) {
  const keep = [];
  for (let i = 0; i < totalPages; i++) if (!indicesToDelete.includes(i)) keep.push(i);
  return rebuildWithOrder(bytes, keep);
}

// Extracts a subset of pages (in the given order) into a brand-new,
// standalone PDF — does not touch the source document at all.
export function extractPages(bytes, indices) {
  return rebuildWithOrder(bytes, indices);
}

// Splits ONE page (e.g. a two-page spread scanned as a single image) into
// two pages in place, replacing it at the same position in the document.
// `axis`: "vertical" (left half / right half) or "horizontal" (top half /
// bottom half, top portion first). Uses the page's own crop box — no
// rasterizing, so vector content (text, lines) stays crisp and selectable.
export async function splitPage(bytes, pageIndex, axis = "vertical") {
  const src = await PDFDocument.load(bytes);
  const out = await PDFDocument.create();

  const srcPage = src.getPage(pageIndex);
  const { x, y, width, height } = srcPage.getCropBox ? srcPage.getCropBox() : { x: 0, y: 0, width: srcPage.getWidth(), height: srcPage.getHeight() };

  const order = [];
  for (let i = 0; i < src.getPageCount(); i++) order.push(i);
  // Copy every page once, plus the target page a second time (for its second half)
  order.splice(pageIndex, 0, pageIndex);

  const copied = await out.copyPages(src, order);
  copied.forEach(p => out.addPage(p));

  const halfA = copied[pageIndex];
  const halfB = copied[pageIndex + 1];

  if (axis === "horizontal") {
    halfA.setCropBox(x, y + height / 2, width, height / 2); // top half
    halfB.setCropBox(x, y, width, height / 2);               // bottom half
  } else {
    halfA.setCropBox(x, y, width / 2, height);               // left half
    halfB.setCropBox(x + width / 2, y, width / 2, height);    // right half
  }

  return out.save();
}

export async function getPageCount(bytes) {
  const doc = await PDFDocument.load(bytes);
  return doc.getPageCount();
}
